package service; import java.io.*; import java.util.*; import model.*;
public class PersistenceService { private static final String FILE="queueless-data.ser";
 private static class Snapshot implements Serializable {private static final long serialVersionUID=1L;ArrayList<Student> students;ArrayList<Staff> staff;ArrayList<Admin> admins;ArrayList<Service> services;ArrayList<Counter> counters;ArrayList<Token> tokens;int tokenCounter;}
 public static synchronized void save(){Snapshot d=new Snapshot();d.students=new ArrayList<>(DataStore.students);d.staff=new ArrayList<>(DataStore.staffMembers);d.admins=new ArrayList<>(DataStore.admins);d.services=new ArrayList<>(DataStore.services);d.counters=new ArrayList<>(DataStore.counters);d.tokens=new ArrayList<>(DataStore.tokenHistory);d.tokenCounter=DataStore.tokenCounter;try(ObjectOutputStream o=new ObjectOutputStream(new FileOutputStream(FILE))){o.writeObject(d);}catch(IOException e){System.out.println("Could not save data: "+e.getMessage());}}
 public static synchronized void load(){File f=new File(FILE);if(!f.exists())return;try(ObjectInputStream in=new ObjectInputStream(new FileInputStream(f))){Snapshot d=(Snapshot)in.readObject();DataStore.students.clear();DataStore.students.addAll(d.students);DataStore.staffMembers.clear();DataStore.staffMembers.addAll(d.staff);DataStore.admins.clear();DataStore.admins.addAll(d.admins);DataStore.services.clear();DataStore.services.addAll(d.services);DataStore.counters.clear();DataStore.counters.addAll(d.counters);DataStore.tokenHistory.clear();DataStore.tokenHistory.addAll(d.tokens);DataStore.tokenCounter=d.tokenCounter;}catch(Exception e){System.out.println("Saved data could not be read; using fresh demo data.");}}
}
